"""Executable deployment preconditions for privileged native-library mitigations."""
from __future__ import annotations

import re

BACKEND_PROCESSES = (
    "backend", "worker", "my-photos-worker", "email-worker", "email-ai-worker",
    "email-beat", "extraction-worker", "verification-worker", "visa-ai-worker",
    "ecr-worker", "database-admin", "database-migrate",
)

WORKER_COMMANDS = {
    "worker": ("general", "passport_ocr,whatsapp"),
    "my-photos-worker": ("my-photos", "my_photos_control,my_photos_index,my_photos_media,my_photos_search"),
    "email-worker": ("email", "email_integrations"),
    "email-ai-worker": ("email-ai", "email_ai"),
    "extraction-worker": ("extraction", "interactive-passport-extraction"),
    "verification-worker": ("verification", "post-submission-ai-verification"),
    "visa-ai-worker": ("visa-ai", "visa-ai-image-edit"),
    "ecr-worker": ("ecr", "ecr_checks"),
}
CELERY_COMMAND = "exec celery -A app.infrastructure.processing.celery_app:celery_app"


def reviewed_process_command(name: str, concurrency: int = 1) -> list[str] | None:
    if name == "backend":
        return None  # The qualified image's Gunicorn command remains authoritative.
    if name == "database-admin":
        return ["python", "scripts/provision_database_roles.py"]
    if name == "database-migrate":
        return ["alembic", "upgrade", "head"]
    if name == "email-beat":
        return ["sh", "-c", CELERY_COMMAND + " beat --loglevel=INFO --schedule=/tmp/passdetection-email-beat"]
    prefix, queues = WORKER_COMMANDS[name]
    return ["sh", "-c", f"{CELERY_COMMAND} worker --hostname={prefix}@%h --loglevel=INFO --concurrency={concurrency} -Q {queues}"]


def validate_process_command(name: str, service: dict) -> None:
    if service.get("entrypoint") is not None or service.get("working_dir") not in (None, "/app"):
        raise ValueError(f"{name}: startup overrides invalidate the reviewed native call paths")
    command = service.get("command")
    expected = reviewed_process_command(name)
    if name in WORKER_COMMANDS:
        if not isinstance(command, list) or len(command) != 3 or command[:2] != ["sh", "-c"]:
            raise ValueError(f"{name}: unreviewed worker command")
        pattern = re.escape(expected[2]).replace(re.escape("--concurrency=1"), r"--concurrency=[1-9][0-9]{0,2}")
        if re.fullmatch(pattern, " ".join(command[2].split())) is None:
            raise ValueError(f"{name}: worker command differs from the reviewed executable and queues")
    elif command != expected:
        raise ValueError(f"{name}: startup command differs from the reviewed image contract")


def validate_code_boundary(name: str, service: dict) -> None:
    if any(service.get(key) for key in ("volumes_from", "tmpfs", "configs", "secrets")):
        raise ValueError(f"{name}: filesystem overlays invalidate the qualified image bytes")
    environment = service.get("environment", {})
    for key, value in environment.items():
        if value is None or value == "":
            continue
        if key.startswith(("LD_", "PYTHON")) or key in {"PATH", "BASH_ENV", "ENV", "GLIBC_TUNABLES"}:
            raise ValueError(f"{name}: interpreter/loader overrides invalidate native-call review")


def validate_process_isolation(services: dict, *, storage_directory: str | None = None) -> None:
    for name in BACKEND_PROCESSES:
        service = services[name]
        validate_code_boundary(name, service)
        validate_process_command(name, service)
        if service.get("user") != "1001:1001":
            raise ValueError(f"{name}: reviewed native-library mitigation requires UID/GID 1001")
        if set(service.get("cap_drop", [])) != {"ALL"} or service.get("cap_add"):
            raise ValueError(f"{name}: all capabilities must be dropped without additions")
        options = set(service.get("security_opt", []))
        if options != {"no-new-privileges:true"}:
            raise ValueError(f"{name}: no-new-privileges and the default confinement are required")
        if service.get("privileged") or service.get("pid") == "host" or service.get("ipc") == "host":
            raise ValueError(f"{name}: host privilege or namespace sharing invalidates the mitigation")
        if service.get("devices") or service.get("device_cgroup_rules"):
            raise ValueError(f"{name}: device access invalidates the reviewed boundary")
        for volume in service.get("volumes", []):
            if volume.get("type") != "bind":
                raise ValueError(f"{name}: runtime volumes must not overlay qualified image bytes")
            # Only the specific, read-only push credential directory is allowed.
            secret = {"/run/gc-fcm": "/opt/global-connect-secrets/fcm",
                      "/run/gc-apns": "/opt/global-connect-secrets/apns"}.get(volume.get("target"))
            if not (name == "worker" and secret and volume.get("source") == secret
                    and volume.get("read_only") is True):
                raise ValueError(f"{name}: unexpected host bind mount invalidates the mitigation")
    if "storage-copy" in services:
        copy = services["storage-copy"]
        validate_code_boundary("storage-copy", copy)
        if (copy.get("user") != "0:0" or set(copy.get("cap_drop", [])) != {"ALL"}
                or copy.get("cap_add") or copy.get("privileged") or copy.get("devices") or copy.get("device_cgroup_rules")
                or copy.get("pid") == "host" or copy.get("ipc") == "host"
                or set(copy.get("security_opt", [])) != {"no-new-privileges:true"}
                or copy.get("command") != ["python", "scripts/copy_storage_snapshot.py"]
                or copy.get("entrypoint") or copy.get("restart") != "no"):
            raise ValueError("storage-copy must retain the exact confined one-off maintenance contract")
        mounts = copy.get("volumes", [])
        # Compose v2 omits false JSON fields, rendering an explicit
        # create_host_path:false as bind:{}. Require that bind object; short
        # syntax renders create_host_path:true and must still be rejected.
        if (len(mounts) != 1 or mounts[0].get("type") != "bind"
                or mounts[0].get("target") != "/evidence"
                or not isinstance(mounts[0].get("bind"), dict)
                or mounts[0]["bind"].get("create_host_path", False) is not False):
            raise ValueError("storage-copy may only mount the existing protected evidence directory")
        expected = storage_directory or services["database-admin"].get("environment", {}).get("OBJECT_STORAGE_MIGRATION_DIRECTORY")
        if not expected:
            raise ValueError("Prepared storage evidence directory is required")
        if mounts[0].get("source") != expected:
            raise ValueError("storage-copy evidence mount differs from the prepared directory")

scripts/release_manifest.py.source:
"""Read the reviewed release contract without importing application settings."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
MANIFEST_PATH = ROOT / "backend/app/core/config/release_manifest.json"


def load_release_manifest(path: Path = MANIFEST_PATH) -> dict[str, Any]:
    manifest = json.loads(path.read_text(encoding="utf-8"))
    if manifest.get("version") != 1:
        raise ValueError("Unsupported release manifest")
    for key in ("schema_revision", "previous_schema_revision"):
        if not re.fullmatch(r"[0-9]{4}_[A-Za-z0-9_]{1,27}", manifest.get(key, "")):
            raise ValueError(f"Invalid release manifest {key}")
    nodes = manifest.get("worker_nodes")
    if not isinstance(nodes, dict) or not nodes:
        raise ValueError("Release manifest must declare worker nodes")
    if any(
        not isinstance(value, str) or not re.fullmatch(r"[a-z][a-z0-9-]*", value)
        for value in (*nodes, *nodes.values())
    ):
        raise ValueError("Invalid release worker identity")
    if len(set(nodes.values())) != len(nodes):
        raise ValueError("Worker node prefixes must be distinct")
    return manifest


def verify_rendered_release(config: dict[str, Any], manifest: dict[str, Any]) -> None:
    """Inspect actual rendered values; never replace stale values with fixtures."""
    services = config.get("services", {})
    for name in (*manifest["worker_nodes"], "email-beat", "backend"):
        service = services.get(name)
        if not isinstance(service, dict):
            raise ValueError(f"Missing release service: {name}")
        environment = service.get("environment", {})
        if environment.get("EXPECTED_DATABASE_SCHEMA_REVISION") != manifest["schema_revision"]:
            raise ValueError(f"{name}: configured schema disagrees with reviewed release manifest")
    for name, prefix in manifest["worker_nodes"].items():
        command = services[name].get("command", [])
        rendered = command if isinstance(command, str) else " ".join(map(str, command))
        if f"{prefix}@" not in rendered:
            raise ValueError(f"{name}: worker node prefix disagrees with release manifest")


def verify_source_defaults(root: Path = ROOT) -> None:
    manifest = load_release_manifest(root / "backend/app/core/config/release_manifest.json")
    schema = manifest["schema_revision"]
    expected = {
        ".env.example": f"EXPECTED_DATABASE_SCHEMA_REVISION={schema}",
        "docker-compose.yml": f"EXPECTED_DATABASE_SCHEMA_REVISION: ${{EXPECTED_DATABASE_SCHEMA_REVISION:-{schema}}}",
    }
    for filename, declaration in expected.items():
        if declaration not in (root / filename).read_text(encoding="utf-8"):
            raise ValueError(f"{filename}: schema default differs from release manifest")


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--rendered-config", type=Path)
    args = parser.parse_args()
    verify_source_defaults()
    if args.rendered_config:
        verify_rendered_release(
            json.loads(args.rendered_config.read_text(encoding="utf-8")), load_release_manifest()
        )
    print("Release contract verified" + (" against actual rendered configuration" if args.rendered_config else " (source defaults only)"))

scripts/verify_deployment_resource_budge.source:
"""Validate a rendered production Compose memory budget without starting it.

Example: docker compose ... config --format json --no-env-resolution > compose.json
python scripts/verify_deployment_resource_budget.py compose.json --host-memory-gib 24
The input may contain credentials; keep it outside source control and never print it.
"""

from __future__ import annotations

import argparse
import json
import math
import re
import shlex
from decimal import Decimal
from pathlib import Path


_BYTE_UNITS = {
    "": 1,
    "b": 1,
    "k": 1024,
    "kb": 1024,
    "m": 1024**2,
    "mb": 1024**2,
    "g": 1024**3,
    "gb": 1024**3,
    "t": 1024**4,
    "tb": 1024**4,
}


def _memory_bytes(value: object) -> int:
    # Rendered Compose normally emits integer bytes; byte strings are also legal.
    if isinstance(value, bool) or not isinstance(value, (int, str)):
        raise ValueError("mem_limit must be a positive byte value")
    match = re.fullmatch(r"(\d+(?:\.\d+)?)\s*([kmgt]?b?)", str(value).strip().lower())
    if not match:
        raise ValueError("mem_limit must be a positive byte value")
    result = Decimal(match[1]) * _BYTE_UNITS[match[2]]
    if result <= 0 or result != result.to_integral_value():
        raise ValueError("mem_limit must be a positive whole number of bytes")
    return int(result)


def _nonnegative_integer(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, (int, str)):
        raise ValueError("requires a nonnegative integer")
    if not re.fullmatch(r"\d+", str(value)):
        raise ValueError("requires a nonnegative integer")
    return int(value)


def _replicas(service: dict) -> int:
    deploy = service.get("deploy", {})
    if not isinstance(deploy, dict) or deploy.get("mode", "replicated") != "replicated":
        raise ValueError("requires a finite replicated service count")
    replicas = _nonnegative_integer(deploy.get("replicas", service.get("scale", 1)))
    if "scale" in service and _nonnegative_integer(service["scale"]) != replicas:
        raise ValueError("scale and deploy.replicas must agree")
    return replicas


def _worker_children(command: object) -> int | None:
    if command is None:
        return None  # Image CMD is outside the rendered Compose command.
    if isinstance(command, str):
        tokens = shlex.split(command)
    elif isinstance(command, list) and all(isinstance(value, str) for value in command):
        tokens = command
    else:
        raise ValueError("command must be a string or an array of strings")
    if "worker" not in tokens or not any(
        token.rsplit("/", 1)[-1] == "celery" for token in tokens
    ):
        return None
    limits = []
    for index, token in enumerate(tokens):
        option, separator, value = token.partition("=")
        if option in {"--concurrency", "-c", "--autoscale"}:
            if not separator:
                value = tokens[index + 1] if index + 1 < len(tokens) else ""
            if option == "--autoscale":
                parts = value.split(",")
                if len(parts) != 2:
                    raise ValueError(
                        "Celery autoscale must declare maximum and minimum children"
                    )
                maximum, minimum = map(_nonnegative_integer, parts)
                if minimum > maximum:
                    raise ValueError("Celery autoscale minimum exceeds its maximum")
                limits.append(maximum)
            else:
                limits.append(_nonnegative_integer(value))
        elif token.startswith("-c") and token[2:].isdigit():
            limits.append(int(token[2:]))
    if not limits or min(limits) <= 0:
        raise ValueError(
            "Celery worker requires explicit positive concurrency or autoscale maximum"
        )
    return max(limits)


def validate_budget(
    config: object, host_gib: float, reserve_gib: float
) -> tuple[list[str], float]:
    failures: list[str] = []
    if (
        not math.isfinite(host_gib)
        or not math.isfinite(reserve_gib)
        or host_gib <= 0
        or reserve_gib < 0
    ):
        return [
            "Host memory must be finite and positive; reserve must be finite and nonnegative"
        ], 0.0
    if (
        not isinstance(config, dict)
        or not isinstance(config.get("services"), dict)
        or not config["services"]
    ):
        return ["Rendered Compose must contain a nonempty services mapping"], 0.0
    total = 0
    for name, service in config["services"].items():
        if not isinstance(name, str) or not re.fullmatch(r"[a-zA-Z0-9_.-]+", name):
            failures.append("Compose contains an invalid service name")
            continue
        if not isinstance(service, dict):
            failures.append(f"{name}: service definition must be a mapping")
            continue
        try:
            memory = _memory_bytes(service.get("mem_limit"))
            replicas = _replicas(service)
            total += memory * replicas
        except ValueError as error:
            failures.append(f"{name}: {error}")
            continue
        try:
            cpu = service.get("cpus")
            if (
                isinstance(cpu, bool)
                or not isinstance(cpu, (int, float, str))
                or not math.isfinite(float(cpu))
                or float(cpu) <= 0
            ):
                raise ValueError
        except (ValueError, OverflowError):
            failures.append(f"{name}: requires an explicit finite positive CPU ceiling")
        try:
            children = _worker_children(service.get("command"))
        except ValueError:
            # Do not echo parser errors: a command can contain credentials.
            failures.append(
                f"{name}: command must declare valid positive Celery concurrency or autoscale limits"
            )
            continue
        if children and (256 + children * 128) * 1024**2 > memory:
            failures.append(
                f"{name}: worker count exceeds the conservative 128 MiB/child plus 256 MiB parent allowance; measure before increasing it"
            )
    total_gib = total / 1024**3
    if total_gib + reserve_gib > host_gib:
        failures.append(
            f"Container ceilings {total_gib:.2f} GiB + host reserve {reserve_gib:.2f} GiB exceed {host_gib:.2f} GiB"
        )
    return failures, total_gib


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("rendered_compose", type=Path)
    parser.add_argument("--host-memory-gib", type=float, required=True)
    parser.add_argument("--reserve-gib", type=float, default=2)
    args = parser.parse_args()
    if (
        not math.isfinite(args.host_memory_gib)
        or not math.isfinite(args.reserve_gib)
        or args.host_memory_gib <= 0
        or args.reserve_gib < 0
    ):
        parser.error(
            "Host memory must be finite and positive; reserve finite and nonnegative"
        )
    try:
        config = json.loads(args.rendered_compose.read_text(encoding="utf-8-sig"))
    except (OSError, UnicodeError, ValueError):
        # JSON and file errors may include private input. Fail without dumping it.
        parser.error(
            "Cannot read rendered Compose JSON; check the local file and encoding"
        )
    failures, total = validate_budget(config, args.host_memory_gib, args.reserve_gib)
    for failure in failures:
        print(failure)
    if not failures:
        print(
            f"Memory envelope verified: {total:.2f} GiB of containers + {args.reserve_gib:.2f} GiB host reserve"
        )
    return int(bool(failures))


if __name__ == "__main__":
    raise SystemExit(main())

scripts/verify_database_deployment_budge.source:
"""Calculate database pools from the actual rendered deployment, including surge.

Input Compose JSON can contain secrets. Output contains numeric capacity only.
The runtime settings validator remains a process configuration guard; this gate
is the deployment guard and must run after all replica/rollout overrides.
"""
from __future__ import annotations

import argparse
import json
import re
import shlex
from pathlib import Path

from verify_deployment_resource_budget import (
    _nonnegative_integer,
    _replicas,
    _worker_children,
)

ROOT = Path(__file__).resolve().parents[1]
POLICY = ROOT / "tooling/database-deployment-budget.json"
MAINTENANCE = {"database-admin", "database-migrate", "storage-copy"}


def calculate(config: dict, policy: dict) -> dict:
    if policy.get("schema_version") != 1 or not policy.get("owner"):
        raise ValueError("A reviewed database capacity policy is required")
    services = config["services"]
    reference = services["backend"]["environment"]
    keys = ("POSTGRES_SERVER_MAX_CONNECTIONS", "POSTGRES_RESERVED_CONNECTIONS", "POSTGRES_API_CONNECTION_BUDGET")
    maximum, reserve, api_budget = (_nonnegative_integer(reference[key]) for key in keys)
    if "db" in services:
        server_command = services["db"].get("command", [])
        if isinstance(server_command, str):
            server_command = shlex.split(server_command)
        if f"max_connections={maximum}" not in server_command:
            raise ValueError("Bundled PostgreSQL command does not match the declared connection ceiling")
    external = _nonnegative_integer(policy["external_connections"])
    maintenance = _nonnegative_integer(policy["maintenance_connections"])
    if maximum <= reserve or maintenance > reserve:
        raise ValueError("Server reserve must cover maintenance and leave application capacity")
    surge = policy["rollout_surge"]
    rows, seen = [], set()
    for name, service in services.items():
        if not re.fullmatch(r"[a-zA-Z0-9_.-]+", name):
            raise ValueError("Invalid service identifier")
        env = service.get("environment", {})
        profile = env.get("POSTGRES_POOL_PROFILE")
        if name in MAINTENANCE:
            if "maintenance" not in service.get("profiles", []):
                raise ValueError("Maintenance database consumers must remain opt-in jobs")
            continue
        if profile is None:
            if env.get("POSTGRES_HOST") and name != "db":
                raise ValueError(f"{name}: database consumer requires an explicit pool profile")
            continue
        if profile not in {"api", "worker"} or name not in surge:
            raise ValueError(f"{name}: unreviewed database consumer or profile")
        seen.add(name)
        if any(env.get(key) != reference[key] for key in keys):
            raise ValueError(f"{name}: inconsistent database capacity declaration")
        replicas, overlap = _replicas(service), _nonnegative_integer(surge[name])
        if profile == "api":
            if service.get("command") is not None:
                raise ValueError("API command override requires a separate reviewed process-count contract")
            processes = _nonnegative_integer(env["WEB_CONCURRENCY"])
        else:
            command = service.get("command")
            tokens = shlex.split(command) if isinstance(command, str) else command
            if isinstance(tokens, list) and len(tokens) == 3 and tokens[:2] in (["sh", "-c"], ["/bin/sh", "-c"]):
                tokens = shlex.split(tokens[2])
            processes = _worker_children(tokens)
            if processes is None and name == "email-beat" and isinstance(tokens, list) and "beat" in tokens:
                processes = 1
            if processes is None:
                raise ValueError(f"{name}: cannot establish database process count")
        pool = _nonnegative_integer(env[f"POSTGRES_{profile.upper()}_POOL_SIZE"])
        overflow = _nonnegative_integer(env[f"POSTGRES_{profile.upper()}_MAX_OVERFLOW"])
        if not processes or not pool:
            raise ValueError(f"{name}: unbounded/zero pool or process count is unsupported")
        rows.append({"service": name, "profile": profile, "replicas": replicas,
                     "surge": overlap, "processes_per_replica": processes,
                     "pool_per_process": pool + overflow,
                     "steady_claim": replicas * processes * (pool + overflow),
                     "peak_claim": (replicas + overlap) * processes * (pool + overflow)})
    if seen != set(surge):
        raise ValueError("Capacity policy consumers differ from the rendered deployment")
    steady = sum(row["steady_claim"] for row in rows)
    peak = sum(row["peak_claim"] for row in rows)
    api_peak = sum(row["peak_claim"] for row in rows if row["profile"] == "api")
    errors = []
    if api_peak > api_budget:
        errors.append(f"API peak claim {api_peak} exceeds API budget {api_budget}")
    if peak + external + reserve > maximum:
        errors.append(f"Peak application {peak} + external {external} + reserve {reserve} exceeds server {maximum}")
    return {"schema_version": 1, "rows": rows, "steady_claim": steady, "peak_claim": peak,
            "external_connections": external, "reserved_connections": reserve,
            "maintenance_connections_within_reserve": maintenance,
            "server_max_connections": maximum, "headroom": maximum - reserve - external - peak,
            "errors": errors}


def capacity_markdown(report: dict) -> str:
    lines = ["<!-- Generated by scripts/verify_database_deployment_budget.py; do not hand-edit numbers. -->",
             "| Consumer | Replicas | Surge replicas | Processes / replica | Pool / process | Peak claim |",
             "| --- | ---: | ---: | ---: | ---: | ---: |"]
    lines.extend(f"| {r['service']} | {r['replicas']} | {r['surge']} | {r['processes_per_replica']} | {r['pool_per_process']} | {r['peak_claim']} |" for r in report["rows"])
    lines.append(f"\nSteady application claim **{report['steady_claim']}**; peak **{report['peak_claim']}**; external **{report['external_connections']}**; operational reserve **{report['reserved_connections']}** (includes **{report['maintenance_connections_within_reserve']}** simultaneous maintenance connections); PostgreSQL maximum **{report['server_max_connections']}**; remaining headroom **{report['headroom']}**.\n")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("rendered_compose", type=Path)
    parser.add_argument("--policy", type=Path, default=POLICY)
    parser.add_argument("--markdown", type=Path)
    parser.add_argument("--check-markdown", type=Path)
    args = parser.parse_args()
    try:
        report = calculate(json.loads(args.rendered_compose.read_text(encoding="utf-8-sig")), json.loads(args.policy.read_text()))
        if args.markdown:
            args.markdown.write_text(capacity_markdown(report), encoding="utf-8")
        if args.check_markdown and args.check_markdown.read_text(encoding="utf-8") != capacity_markdown(report):
            report["errors"].append("Generated capacity documentation is stale")
        print(json.dumps(report, indent=2))
        return int(bool(report["errors"]))
    except (OSError, ValueError, KeyError, TypeError):
        parser.error("Invalid or incomplete database capacity input; no private configuration was printed")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

